def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently and return results in input order.

    Any coroutine not finished within ``seconds`` is cancelled and its
    result position is ``None``. Exceptions from completed coroutines
    propagate immediately. Intended for use from ordinary synchronous
    code with no running event loop.
    """

    async def _main():
        tasks = [asyncio.create_task(coro) for coro in coros]
        try:
            done, pending = await asyncio.wait(
                tasks, timeout=seconds, return_when=asyncio.ALL_COMPLETED
            )

            results = [None] * len(tasks)

            # Propagate exceptions from completed tasks and collect results.
            for idx, task in enumerate(tasks):
                if task in done:
                    results[idx] = await task

            # Cancel anything still pending and wait for cancellation to finish.
            for task in pending:
                task.cancel()
            if pending:
                await asyncio.gather(*pending, return_exceptions=True)

            return results
        finally:
            # Defensive cleanup in case of unexpected errors.
            for task in tasks:
                if not task.done():
                    task.cancel()

    return asyncio.run(_main())

