import asyncio
from typing import Any, List


async def _run_with_deadline_async(coros, seconds: float) -> List[Any]:
    tasks = [asyncio.create_task(coro) for coro in coros]
    try:
        done, pending = await asyncio.wait(tasks, timeout=seconds)

        # Propagate the first exception from any completed task.
        for task in done:
            exc = task.exception()
            if exc is not None:
                for p in pending:
                    p.cancel()
                if pending:
                    await asyncio.gather(*pending, return_exceptions=True)
                raise exc

        results = [None] * len(tasks)

        for index, task in enumerate(tasks):
            if task in done:
                results[index] = task.result()
            else:
                results[index] = None

        for p in pending:
            p.cancel()
        if pending:
            await asyncio.gather(*pending, return_exceptions=True)

        return results
    finally:
        # Ensure no task is left pending if anything goes wrong.
        for task in tasks:
            if not task.done():
                task.cancel()
        if tasks:
            await asyncio.gather(*tasks, return_exceptions=True)


