    return asyncio.run(_run_with_deadline_async(coros, seconds))

from web_utils import content_charset, parse_content_type, image_type


def describe_upload(content_type: str, data: bytes) -> dict:
    """
    Describe an uploaded payload from its Content-Type header and leading bytes.

    Returns:
        {
            "mime": <lower-cased media type without parameters>,
            "charset": <lower-cased charset parameter or None>,
            "image": <"png", "jpeg", "gif" or None>,
        }
    """
    mime, params = parse_content_type(content_type)
    charset = params.get("charset")
    if charset is not None:
        charset = charset.lower()

    image = image_type(data)
    if image not in {"png", "jpeg", "gif"}:
        image = None

    return {
        "mime": mime,
        "charset": charset,
        "image": image,
    }

"""Utilities for running coroutines from synchronous code with a global deadline."""
import asyncio
from typing import Any, List


def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently from synchronous code, returning results in input order.

    Coroutines that do not finish within `seconds` are cancelled and represented by None.
    This function is safe to call repeatedly in the same process.
    """
    async def _runner():
        tasks = [asyncio.create_task(coro) for coro in coros]
        try:
            done, pending = await asyncio.wait(
                tasks, timeout=seconds, return_when=asyncio.ALL_COMPLETED
            )

            for task in pending:
                task.cancel()

            if pending:
                await asyncio.gather(*pending, return_exceptions=True)

            results = []
            for task in tasks:
                if task.cancelled():
                    results.append(None)
                else:
                    exc = task.exception()
                    if exc is not None:
                        raise exc
                    results.append(task.result())
            return results
        except BaseException:
            for task in tasks:
                if not task.done():
                    task.cancel()
            await asyncio.gather(*tasks, return_exceptions=True)
            raise

    return asyncio.run(_runner())
